{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_7",
      "quote": "The inclusion criteria, based on the PICO framework, are as follows: ① Population: Patients with post-stroke depression (PSD) meeting the diagnostic criteria. ② Intervention: The experimental group includes TCE such as Tai Chi, Baduanjin, Yijinjing, and Wuqinxi, while the control group receives standard care, health education, or routine treatment. ③ Outcome: Primary outcomes include the efficacy of TCE in alleviating depression, assessed using the Hamilton Depression Rating Scale (HAMD) scores and Overall Efficacy Rate. Secondary outcomes include FMA (Fugl-Meyer motor function assessment) and BI (Breteau Index) scores. ④ Study Design: Only randomized controlled trials (RCTs) were included.",
      "reason": "PICO components and eligible study design (RCTs) are explicitly specified, but settings and follow-up requirements are not reported."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_8",
      "quote": "① Dissertations, conference proceedings, studies without full text access, or those with missing data.",
      "reason": "The report specifies exclusions by publication/report status (e.g., dissertations, conference proceedings, unavailable full text), but does not state restrictions by dissemination year or explicitly state language restrictions (although elsewhere they note that both Chinese and English literature were screened, there is no explicit eligibility statement on language or years)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No explicit distinction is made between excluding studies because outcomes were not measured versus excluding because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "② Intervention: The experimental group includes TCE such as Tai Chi, Baduanjin, Yijinjing, and Wuqinxi, while the control group receives standard care, health education, or routine treatment.",
      "reason": "The review specifies the groups used in syntheses (experimental TCE group versus control receiving standard care/education/routine treatment), linking these groups to the review comparisons."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No explicit rationales are provided for notable restrictions on study eligibility (e.g., why only RCTs, or why certain publication types were excluded) beyond general background."
    }
  ],
  "confidence": "85"
}

